    let ans = Infinity;
    for (let c = 0; c < numCycles; c++) {
      if (cycleLens[c] >= T && cycleDist[c] < INF) {
        const cost = 2 * cycleDist[c] + cycleLens[c];
        if (cost < ans) {
          ans = cost;
        }
      }
